    title: '英伟达开放 30B MoE 生图模型权重：密集文字渲染超 GPT Image 2，但许可限非商业研究',
    excerpt: '英伟达 11 月 25 日在 Hugging Face 悄然公开 Nemotron-Labs-Image-30B-A3B 权重，总参数约 300 亿、推理激活约 30 亿，是 Nemotron-Labs-VisualCreation 框架的核心光栅渲染引擎。官方披露其在 LongTextBench、GenEval 等基准领先 GPT Image 2，但在 GenEval2、Qwen-Image-Bench 上明显落后；使用范围被限定于非商业研究和评估，并非不受限制的商业开源许可。',
    summary: '英伟达开放 30B 生图模型权重，仅激活 3B；密集文字基准超 GPT Image 2，GenEval2 等仍落后，且许可限非商业研究。',
    source: '凤凰网科技 · IT之家 · 英伟达 Hugging Face',
    url: 'https://news.qq.com/rain/a/20261125A0E5VL00',
    minutes: 4,
    body: [
      { h: '权重悄然上线，许可并非完全开源', p: '英伟达 11 月 25 日在 Hugging Face 公开 Nemotron-Labs-Image-30B-A3B 权重，包含模型权重、视觉分词器、模型定义与推理代码，Hugging Face 记录显示首个公开版本于北京时间 11 月 25 日 5 时 55 分提交。模型采用混合专家架构，总参数约 300 亿、推理时激活约 30 亿，另搭载约 6.42 亿参数的视觉分词器；官方参考方案用 4 张 H100 80GB 生成 1024×1024 图片。需要区分的是，其使用范围被限定于非商业研究和评估，并非不受限制的商业开源许可。' },
      { h: '文字与图表领先，通用生成仍落后', p: '模型是自回归图像生成器，基于 Nemotron 3 Nano、沿用 Nemotron-H 混合设计，把 Mamba-2 状态空间层与传统注意力结合，并经渐进式中期训练和组相对策略优化（GRPO）。英伟达披露在考察密集文字生成的 LongTextBench 上得 97.98，高于 GPT Image 2 的 96.00 和 Nano Banana Pro 的 97.60；GenEval 92.86 领先 GPT Image 2 的 89.00，BizGenEval 86.0 对 83.2。但在 GenEval2 上以 65.43 落后于 GPT Image 2 的 81.00，Qwen-Image-Bench 也以 52.46 落后于 65.23。' },
      { h: '「像素即代码」的定位', p: '该模型是英伟达新框架 Nemotron-Labs-VisualCreation 的核心光栅渲染引擎，框架主打「像素即代码」，除生成图片外还产出可编辑的网页、幻灯片、文档、图表和科学插图等结构化视觉成果。英伟达已把模型权重和相关论文同步放到 Hugging Face 与 arXiv。上述跑分均为发布方口径，且多为完整框架的最佳成绩，尚无第三方复现；对图表、幻灯片这类场景，文字准确率与可编辑性仍需实测。' }
    ],
