    excerpt: '记者从农业农村部了解到，首个农耕文明领域大模型「天稷」发布，11 月 27 日经央视新闻、中国网等集中报道。模型由中国农科院农业信息研究所自主研发，涵盖 8000 万条知识条目，整合跨时空文本、音视频影像、地理信息、传统历法等多维数据，搭建古农书智能解译、二十四节气应用、农业文化遗产活化等智能体模块。',
    summary: '中国农业科学院信息所发布农耕文明时空多模态大模型「天稷」，涵盖 8000 万条知识条目，可解读古农书、还原传统农具并为生产提供决策建议。',
