      { h: '8000 万条条目与三类智能体', p: '央视报道称，「天稷」涵盖 8000 万条覆盖传统农耕技艺、现代智慧农业与农耕文明演进脉络的知识条目，整合跨时空文本、多源音视频影像、地理信息、传统历法等多维数据，依托多模态大模型、时空知识图谱、知识增强与智能推理技术，搭建古农书智能解译、二十四节气应用、农业文化遗产活化等专业化智能体模块。中国农科院表示还将推进农史文献数字化、古籍智能整理和古农文大模型建设。' },
      { h: '解决的是碎片化，而非通用能力', p: '按发布方表述，模型针对的是传统农耕文明研究里古今时空割裂、数据分散孤立、知识体系碎片化的问题，可解读古农书里的节气物候耕种智慧、数字化还原传统农具与农业遗产场景、拆解农业老技艺流程，并为现代农业生产提供智慧决策建议。官方通稿未披露模型参数规模、基座、训练数据构成与评测分数，也未说明是否已对外开放使用；这些边界决定了它目前更像一套行业知识工程，而非可比较的通用模型。' }
