    title: '国家数据局就《完善数据规则 赋能人工智能创新发展的若干意见》公开征求意见',
    excerpt: '国家数据局 11 月 26 日发布《关于完善数据规则 赋能人工智能创新发展的若干意见》（公开征求意见稿），据新华网，文件围绕人工智能发展的数据要素需求，从三大方面提出十二项具体举措，明确推动数据产权制度在人工智能用数领域运用，数据有序、依法合规用于训练和推理。征求意见时间为 11 月 26 日至 12 月 6 日。',
    summary: '国家数据局 11 月 26 日发布征求意见稿，从三大方面提出十二项举措，明确合法获取的数据可用于 AI 训练和推理，鼓励为数据付费，征求意见至 12 月 6 日。',
    source: '国家数据局 · 中新网 · 新华网',
    url: 'https://news.qq.com/rain/a/20261127A06R9Z00',
