    excerpt: '据英国《金融时报》11 月 26 日报道，英伟达已要求制造合作伙伴停止向马来西亚、新加坡、泰国和印度尼西亚运送装其芯片的服务器。戴尔、超微电脑等厂商已通知四国买家，英伟达不允许相关订单发货；英伟达及伙伴正评估如何满足华盛顿新出口管制规则的合规要求，尚不清楚停运是否只是暂时举措。',
    summary: '据金融时报，英伟达已要求戴尔、超微等制造伙伴停止向四个东南亚国家发运装其芯片的服务器，以符合美国新出口管制规则，是否暂时措施尚不明确。',
