      { h: '新规要堵的是第三国租算力', p: '海峡时报报道，这批新规于上周生效，要求向若干东南亚国家发运先进芯片需申请出口许可，目的是关掉中国企业被指通过第三国数据中心租用算力获取先进 AI 芯片的通道。The Star 援引 FT 称，受影响买家包括新加坡云计算公司 Aolani，其原计划通过租赁协议向字节跳动提供英伟达硬件；当地一家云服务商高管称，新规在 90 天许可申请窗口内给区域业务造成了极大混乱。' },
      { h: '影响量级与事件边界', p: '东南亚对英伟达是重要市场：公司账目显示 2025 年经新加坡子公司录得 1040 亿美元营收、12 个月内增长 72%。券商中国援引日经亚洲称，受美国最新出口管制政策影响，至少两家英伟达服务器合作厂商此前已暂停向东南亚客户发货。需要区分的是，本次停运是上周生效的出口管制新规落地后的企业执行动作，属规则后续；规则本身及更早的限制此前已另行报道。' }
