      '本季新增订单 602 亿、季末 AI 积压订单创纪录 1323 亿美元；超 7500 家 AI 工厂客户，订单需审融资能力与土地、电力条件，整机柜到货 6 小时内上架',
      'FY27 营收指引 1920→2020 亿美元、AI 服务器目标 740→780 亿，追加 250 亿回购；管理层预计 2027 供需缺口扩大、DRAM/NAND 紧张延续'
