    excerpt: '11 月 25 日第八届小鹏科技日在广州举行，发布贯通智能汽车与人形机器人的「图灵具身智能架构」VLA 3.0，以 System 0/1/2 分层让一套底座支撑两类本体；IRON 现场用中英文演讲，官方称 76 个自由度、3 颗自研图灵芯片共 2250 TOPS。公司给出 2027 年一季度进门店训练、二季度对外发布的时间表，量产节点由媒体转述为何小鹏现场所说的 2027 年 1 月。',
    summary: '小鹏 11 月 25 日科技日发布图灵 VLA 3.0 架构，IRON 人形机器人拟 2027 年量产；官方称 76 自由度、3 颗图灵芯片 2250 TOPS。',
