      { h: '核心卖点是收费方式', p: '公司称成立约两年半 ARR 已超 4 亿美元，并把增长归因于三点：按结果收费而非用量或 token（问题解决、贷款发放、理赔赔付、订阅挽回）、用 Ghostwriter 让企业团队自行构建与迭代智能体、以及多模型编排。官方博客列举的客户包括 BNY、Cigna、JPMorganChase、HSBC、Wells Fargo、Santander 等，多为受强监管行业的老牌机构。' },
      { h: '按结果收费把风险移到卖方', p: '英文分析指出，推理、集成、重试与失败尝试的成本都发生在收入确认之前，未达成的结果无法计费，这把交付风险从买方转回卖方，也让毛利率、服务成本与净收入留存成为关键——而这几项公司均未披露。4 亿美元是年化经常性收入口径，为公司自报、未经审计，不等于已审计的年销售额或利润。' }
