    excerpt: '11 月 25 日观察者网从企查查获悉，北京行云集成电路有限公司完成工商变更，新增宁德时代全资子公司问鼎投资等为股东，注册资本增至 899.46 万元。该笔近 8 亿元融资由宁德时代领投，约两个月前已有媒体披露，此次为股权登记落地。',
    summary: '11 月 25 日行云集成工商变更落地，宁德时代领投的近 8 亿元融资完成登记，标的是主攻大模型推理的全自研 GPU。',
