    title: '亚马逊约 75 亿美元买下 Decart 优化栈与团队：只收技术，不收模型',
    excerpt: '11 月 23 日亚马逊宣布已签署协议，收购 Decart Optimization Stack 专有技术及三位联创与研究员工程师团队，不含其 AI 模型。官方未披露作价，彭博等报约 75 亿美元，较 5 月约 40 亿美元估值高约 88%，交易尚需监管审批。',
    summary: '亚马逊 11 月 23 日官宣收购 Decart 优化栈技术与创始团队、不含 AI 模型，据报作价约 75 亿美元，意在压低 Trainium 上的推理成本。',
    source: '亚马逊官方公告 · 彭博社 · 观点网',
    url: 'https://news.qq.com/rain/a/20261124A05DXS00',
    minutes: 4,
    body: [
      { h: '买的是跨芯片迁移能力，不是模型', p: '亚马逊 11 月 23 日通过公司公告宣布已签署协议，收购以色列初创公司 Decart 的 Decart Optimization Stack（DOS）专有技术，并吸纳三位联合创始人 Dean Leitersdorf、Moshe Shalev、Orian Leitersdorf 及该团队 AI 研究员与工程师，明确不包括 Decart 的 Lucy、Oasis 等 AI 模型。DOS 能让 AI 模型在不同硬件上同步并快速切换，覆盖英伟达、亚马逊、谷歌芯片。Decart 成立于 2023 年，是 AWS Trainium3 的早期使用方，双方自 2025 年起合作优化 Trainium 表现。' },
      { h: '75 亿是媒体口径，官方没认', p: '亚马逊未披露交易金额，彭博援引消息人士称约 75 亿美元；据观点网整理，代价含现金与股票、部分款项分阶段支付，创办人同意留任 5 年，交割尚需监管审批。按 75 亿计算，较 Decart 2026 年 5 月 3 亿美元 B 轮后约 40 亿美元估值高约 88%。Anthropic 曾于 8 月以约 60 亿美元深入磋商并基本完成尽调，9 月退出，Globes 称分歧之一是创始团队不愿大举从特拉维夫迁往旧金山；英伟达此前也曾洽谈收购并参与 5 月那轮融资。' },
      { h: '瞄准的是 CUDA 的迁移成本', p: '亚马逊负责基础模型、自研芯片与量子计算的高级副总裁 Peter DeSantis 称，提高每枚芯片的运算效率有助加快训练与推理、降低客户成本；公司还计划把 Trainium 卖给外部数据中心，但对外供货时点各家口径不一（早报称明年起，英文报道引 Jassy 称最快 2027 年底）。Evercore ISI 分析师 Mark Mahaney 认为，对约百人团队而言价格看似偏高，但仅占亚马逊市值约 0.3%，是加速 Trainium 进展的「便宜方式」。GeekWire 留下的开放问题是：DOS 被收购后是否继续支持英伟达与谷歌芯片，亚马逊没有回答。' }
    ],
    points: [
      '11 月 23 日官宣签署协议，收购 Decart Optimization Stack 技术与三位联创及团队，不含 AI 模型，交易需监管审批',
      '亚马逊未披露作价，彭博报约 75 亿美元，较 5 月约 40 亿美元估值高约 88%；Anthropic 曾以约 60 亿洽谈后 9 月退出',
      'DOS 用于跨英伟达/亚马逊/谷歌芯片切换，服务 Trainium 降本；未说明收购后是否继续支持竞品芯片'
    ],
    why: '芯片竞争的瓶颈已从硅设计转到「换硬件有多贵」，亚马逊把专门降低迁移成本的工具收归己有，同时也收走了 Anthropic 手里的一张牌。'
