      '建议含国家美国开源计划、模型溯源标准，以及把 10 月 DeepSeek 联邦禁令扩大到所有中国开发模型；目前只是建议',
      'Cursor 称考虑弃用中国开源模型（Composer 2 基于 Kimi K2.5），Airbnb 用 Qwen、DoorDash 部署 25 个中国模型家族；报告自认同价开源替代缺位'
