    excerpt: '11 月 18 日技术报告称，模型重写 SystemVerilog RTL，在 AMD 高度优化的旗舰 GPU IP 上取得最高 14% 的功耗性能面积改进，约一年进展压缩到不到 5 个月。',
    summary: 'OpenAI 11 月 18 日披露模型辅助芯片设计成果：AMD 旗舰 GPU PPA 最高提升 14%，部分改动已送厂制造。',
    source: 'OpenAI 官方 · IT之家',
    url: 'https://openai.com/index/advancing-chip-design-with-our-models',
