      { h: '改的是要流片的电路', p: 'OpenAI 11 月 18 日发布技术报告《Advancing chip design with our models》，称其模型通过重写描述芯片电路的 SystemVerilog RTL 代码，在 AMD 旗舰 GPU IP 上相对高度优化的基准取得最高 14% 的功耗、性能与面积（PPA）改进，并用 Synopsys 工具验证每次重写都保持了模块行为。OpenAI 把这描述为「约一年的进展在不到 5 个月内完成」。AMD 已把部分改动纳入一项近期送交制造的芯片设计，其余加入生产设计文件供后续版本使用；在其下一代旗舰 CPU 的关键模块上，AMD 验证了模型所写设计带来个位数百分比的 PPA 提升。' },
      { h: '自研芯片与开源核上的对照', p: '对自研推理芯片 Jalapeño，OpenAI 称 2025 年初起用 GPT-4o 辅助设计，模型提出的修改使向量单元标准单元面积减少约 13%、矩阵单元约 10%；其中一项乘法器重设计让综合后面积减少约 15%、延迟从两个时钟周期降到一周期，另一加法器面积减少约 15% 而保持两周期延迟，这些优化在 Jalapeño 点亮时经硅验证。为比较代际能力，团队用两个开源 32 位 RISC-V 核 PicoRV32 与 Ibex 测试，在约 112,000 token 的可比预算下 GPT-6.2 Astra 平均分最高，GPT-6.1 Sol 高于 GPT-5.6 Sol，共 9,881 次评分运行。' },
      { h: '厂商自己写了局限', p: 'OpenAI 提示一项可能被高估的结果：五个模型在「按需求文档从零设计核」上的得分都高于「优化现有核」，原因可能是从需求出发时省略了性能计数器、额外指令等特性，未必真正提升能力；要贴近生产，需强制保留特性、收紧面积上限并在物理综合后检查时序。公司同时宣布与 Synopsys 合作训练 GPT-Synopsys，让模型像芯片工程师那样使用 EDA 工具。报告中 AMD 相关数字全部来自 OpenAI 及合作方描述，AMD 未单独发布说明。' }
