    excerpt: '2026 年第 30 号公告 11 月 16 日发布、即日实施，由 TC8 标委会归口，覆盖智能化能力分级、一体化关节、灵巧手、训练场与训练数据全生命周期。',
    summary: '工信部 11 月 16 日发布 5 项人形机器人领域标准并即日实施，首次建立 L0 到 L5 的智能化能力分级框架，覆盖关节、灵巧手与训练数据。',
    source: '澎湃新闻 · 工业和信息化部',
    url: 'https://www.toutiao.com/a7709134082295202314',
