    body: [
      { h: '五项标准一次落地', p: '据澎湃科技 11 月 17 日从工信部人形机器人与具身智能标准化技术委员会（MIIT/TC8）秘书处获悉，工信部 11 月 16 日发布 2026 年第 30 号公告，五项由该标委会归口的标准正式发布，自发布之日起实施。分别是《人形机器人智能化能力分级》《人形机器人电驱动一体化关节技术规范》《人形机器人与具身智能灵巧手技术规范》《人形机器人训练场构建技术规范》和《人形机器人训练数据管理要求》。' },
      { h: 'L0 到 L5 怎么分', p: '《人形机器人智能化能力分级》围绕感知认知、决策学习、执行表现、协作交互四个维度，建立 L0 到 L5 的分级框架，为研发、检测评估、应用选型和场景适配提供依据。零部件两项分别针对躯干、腿部等核心关节的接口、性能指标与测试方法，以及灵巧手的设计、测试、评价与交付，指向接口不统一、整机集成效率不高的问题。' },
      { h: '训练数据管到销毁', p: '训练场构建规范明确功能分区、空间布局、设备、数据采集、通信网络与安全防护要求，衔接数据采集、模型训练、仿真验证与真机验证。训练数据管理要求覆盖采集、预处理、标注、质量评价、存储、流通、使用及销毁全生命周期，推动数据格式、标注规则与质量评价方法统一。TC8 秘书处称后续将推进宣贯、实施与效果评估，并与检测认证、训练平台衔接。' }
    ],
