    summary: '腾讯 11 月 16 日发布 Hy4 flash：224B 总参数、激活 12B，1M 上下文，输入 0.5 元/百万 tokens、缓存 0.02 元，单任务成本为旗舰 Hy4 的 1/20。',
    source: '观察者网 · 每日经济新闻',
    url: 'https://www.163.com/dy/article/LBSC8DSK051481US.html',
    minutes: 3,
    body: [
      { h: '用架构换成本', p: 'Hy4 flash 总参数 224B，其中 64B 是 Engram 参数，每个 token 只激活 12B；通过混合注意力、LatentMoE 与 Engram 设计把 KV cache 压到 Hy4 的六分之一，配合 megakernel 与 4bit 量化，解码速度超过 150 tps。官方称综合效果略优于 770B 的 Hy4 preview，单任务成本只有它的 1/13、标准版 Hy4 的 1/20。' },
      { h: '价格是主叙事', p: '每百万 tokens 输入 0.5 元、输出 2 元，命中缓存仅 0.02 元；11 月 30 日前 API 五折。腾讯称按内部评测集测算，其单任务成本是 DeepSeek-V4.1-Flash-1027（Max 档、忙时价）的八分之一；85 位内部用户、27 类共 259 个任务的盲测中，满意度接近 Claude Haiku 5.5，端到端耗时最短。' },
      { h: '高低搭配，而非替代', p: '混元团队的建议很明确：深度搜索、文档处理、PPT 生成这类日常任务交给 Hy4 flash，长程软件工程留给智能上限更高的 Hy4。Hy4 flash 后续也将开源。同日阿里发布 2.4T 的 Qwen4-Max、称单任务成本降约 60%——两家第一次把「完成一个任务多少钱」而不是 API 单价摆到台前。' }
    ],
