    title: '中国信通院发布 EAI Bench 工业场景真机评测：7 个开源模型、3234 轮测试，20 家单位共发起可信具身倡议',
    excerpt: '9 月 20 日至 10 月 26 日针对分拣、装配等 7 项任务完成 147 次、3234 轮真机测试；领先模型基础抓放跨本体平均成功率约 73%，开关分拣等组合达 95%；结果 11 月 12 日对外披露。',
    summary: '中国信通院发布首个工业场景具身智能大规模真机评测 EAI Bench：7 个开源模型、3 款公版机完成 147 次、3234 轮测试，并联合 20 家单位发起可信具身智能倡议。',
