    url: 'https://m.10jqka.com.cn/20261113/c681783269.shtml',
    minutes: 3,
    body: [
      { h: '统一考题的真机测试', p: '中国信通院人工智能所具身智能测试实验室于 9 月 20 日至 10 月 26 日组织 EAI Bench 工业场景专项评测：针对分拣转运、装配、包装、上下料等 7 项代表性任务，覆盖 Physical Intelligence、英伟达、蚂蚁灵波、乐聚、星海图、北京人形、小米机器人等 7 个开源模型与 3 款「公版机」本体，统一示教、部署与评分规范，累计完成 147 次、3234 轮真机测试。结果于 11 月 12 日对外披露。' },
      { h: '成绩单的读法', p: '参评模型以匿名编号披露：领先的 Model A 在 7 项任务中 4 项跨本体综合得分第一，基础抓放任务跨本体平均成功率约 73%；Model B 与两款本体的组合在开关分拣、减震器下料两个任务上成功率均达 95%。共同规律是：用大规模异构真机数据或 UMI 无本体数据预训练的模型跨本体迁移更好，以人类视频为主要预训练数据的模型与真机适配度有限。' },
      { h: '配套的信任基建', p: '11 月 10 日的发布会上，信通院还联合产业界启动具身世界模型评测体系建设，颁发首批可信具身智能评测证书——天工 3.0、KUAVO 4 PRO MAX A、Moz1、AlphaBot 2 四款本体获「公版机」证书；并与埃夫特、优必选、越疆等 20 家单位共同发起《可信具身智能倡议》，围绕应用边界物理防护、急停互操作、用户权益等提出八项倡议。' }
    ],
