    excerpt: '新增可跨手机与桌面应用自主行动的「视觉代理能力」；官方基准称部分指标超越 GPT-5.2、Claude Opus 4.5 与 Gemini 3 Pro，提供开放权重与 Qwen3.5-Plus 云托管两种形态。',
    summary: '阿里 11 月 15 日发布 Qwen3.5：推理成本较前代降 60%，大负载处理能力提升 8 倍，新增跨手机与桌面自主操作的视觉智能体能力，开放权重与托管双版本。',
    source: '钜亨网 · LINE TODAY',
    url: 'https://today.line.me/tw/v3/article/vXMVNPj',
    minutes: 3,
    body: [
      { h: '降成本是主叙事', p: '11 月 15 日（周一），阿里巴巴发布新一代模型 Qwen3.5，官方称其为「智能体 AI 时代」打造：推理使用成本较前代降低 60%，处理大型工作负载的能力提升至前代的 8 倍，并新增可跨手机与桌面应用自主采取行动的「视觉代理能力」。模型以开放权重发布，同时提供云托管版 Qwen3.5-Plus。' },
      { h: '基准均为自报', p: '阿里称多项基准测试优于前代，并在部分指标上超过 GPT-5.2、Claude Opus 4.5 与 Gemini 3 Pro；值得注意的是，官方公告并未提及 DeepSeek。第三方报道指出这些成绩均来自公司自建基准、尚无独立验证——竞争叙事与实测之间的落差，需要等开放权重上线后由社区检验。' },
      { h: '大模型做入口', p: '发布背景是国产模型竞速：字节跳动日前推出 Doubao 2.0，同样定位智能体时代，其聊天应用用户接近 2 亿；路透此前报道称，阿里本月早些时候以优惠券活动带动 Qwen App 活跃用户短期增长 7 倍，期间出现部分系统故障。成本下降与入口运营并举，显示竞争重心已从单点能力比拼转向规模化交付。' }
    ],
    points: [
      '推理成本较前代降低 60%，大负载处理能力提升至 8 倍',
      '新增跨手机与桌面应用自主行动的视觉智能体能力',
      '开放权重与 Qwen3.5-Plus 云托管双形态，基准成绩为官方自报'
    ],
    why: '当「每单位成本的能力」成为主要卖点，模型竞争的计价单位正从跑分转向智能体任务的单次完成成本。'
