    excerpt: '定位日常编程与多步骤智能体任务：默认高思考档比 Gemini 3.8 Flash 快 2.5 倍，虚构错误率降 5 倍；输入 1.5 美元/百万 token，1M 上下文，免费用户可用。',
    summary: '谷歌发布 Gemini 4 Hydrogen 执行档模型：较 3.8 Flash 快 2.5 倍，Terminal-Bench 从 18.2% 升至 57%，1M 上下文，免费用户可自动调用。',
    source: '快科技 · 凤凰网科技',
