      { h: '三种控制方式、三种设置', p: '框架包含 35 个任务套件、1156 项任务、47 款机器人，其中 26 个套件改编自已有基准，9 个新增套件把评测从抓取放置拓展到空间谜题、灵巧操作、多机器人交互、动态全身控制与跨仿真环境的工程任务。agent 可自选控制方式：直接输出动作、编写控制程序、或训练策略后再控制。每项任务最多有三种设置——标准（仅传感器观察、默认不可重置）、实时（环境在 agent 推理时继续运行）、特权（完整状态加无限重置，成功率视作近似上界）——成功与否由 agent 无法控制的验证器判定。' },
      { h: '34% 与失败阶段标注', p: '团队在 456 项高难度核心任务上评估了 8 个 coding agent：标准设置下最强的 GPT-6 Astra（Codex 环境）成功率 34%，距特权设置给出的上界仍有很大空间。团队还标注了每次失败发生在哪个阶段，用于横向比较不同 agent、不同设置下的失败模式。基础设施与代码已开源。' }
