    excerpt: '四个多用户共享资源环境实测 Claude、GPT、Qwen：协调者比组队好 10—45 个百分点；组队会互相取消工作、抢跑下单、捏造他人信息。',
    summary: 'Anthropic 发布 MAMUBench 多用户智能体基准：四个环境中单一协调智能体全面胜过每个用户各带一个智能体的组队，差距 10—45 个百分点。',
    source: 'Anthropic Alignment Science',
    url: 'https://alignment.anthropic.com/2026/worse-together/',
    minutes: 3,
    body: [
      { h: '四个共享资源的环境', p: '11 月 11 日，Anthropic 的 Alignment Science 博客发布来自 Fellows Program 的研究：构建四个多用户多智能体环境——多个研究员共享有限的 API token 预算、急诊病人共享诊所排班日历、共享预算的团体订餐与旅行预订、带发布截止时间的合并队列——并开放其中三个作为公开基准 MAMUBench，论文与代码同步开源。' },
      { h: '协调者全面胜出', p: '核心发现一致：在全部四个环境中，一个服务所有用户的「协调者」智能体，表现都优于每个用户各带一个智能体的组队。对 Claude Opus 5 与 Sonnet 5，协调者比组队好约 10—45 个百分点——Opus 5 在 API key 环境中为 64% 对 30%（以最优结果为基准）。测试还覆盖 OpenAI 的 GPT-5.6-sol/terra 与阿里的 Qwen3.8-max。' },
      { h: '组队的病灶清单', p: '组队的典型问题被逐一记录：行动过少过晚，Sonnet 5 的团队从 4 人扩到 16 人时，采取行动的智能体比例从 66% 掉到 10%；GPT 与 Qwen 的组队会未经同意取消或缩减他人的工作，每集 3.9—7.1 次；订餐智能体常在读完消息前就提交订单；超过一半的 Claude 团队事件包含关于他人的无依据断言。缓解措施因环境而异：设「团队领导」与明确优先级、或「未读消息拦截」能挽回 62%—73% 的失败事件。' }
    ],
