      { h: '/swarm 与安全能力', p: 'Antigravity 同时预览 /swarm：一条提示词被拆成架构、编码、审计与对抗验证等角色，在并行隔离的工作区里协同，进度可实时追踪。安全侧，谷歌内部项目 Fortify 中 Carbon 的扫描召回率 100%、分诊精确率 95%；在开源代码仓库测试中，召回率相对 Argon 提升 25% 以上，找出了此前未发现的真实逻辑缺陷。谷歌未说明免费与低价订阅层何时能用上 Carbon。' }
