    summary: '智元开源终身具身智能框架 LIFE，含 RoboBeats 0.8B/2B/4B 决策模型与可塑性记忆，24 小时真机录像 6 题问答得 29.5/30 分，平均 80.6 秒。',
    source: '上海证券报 · 上观新闻',
